def fizz_buzz() -> None:
    """
    Prints numbers 1 to 100, replacing multiples of 3 with 'Fizz', multiples of 5 with 'Buzz',
    and multiples of both with 'FizzBuzz'.
    """
    for number: int in range(1, 101):
        if number % 3 == 0 and number % 5 == 0:
            print("FizzBuzz")
        elif number % 3 == 0:
            print("Fizz")
        elif number % 5 == 0:
            print("Buzz")
        else:
            print(number)

from typing import List

def next_greater_elements(nums: List[int]) -> List[int]:
    stack: List[int] = []
    result: List[int] = [-1] * len(nums)

    for i in range(len(nums) - 1, -1, -1):
        while stack and stack[-1] <= nums[i]:
            stack.pop()
        if stack:
            result[i] = stack[-1]
        stack.append(nums[i])

    return result

def check_key(dictionary, key):
    # Check if the key exists in the current dictionary
    if key in dictionary:
        return True

    # Check nested values: dictionaries and lists
    for value in dictionary.values():
        if isinstance(value, dict):
            if check_key(value, key):
                return True
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict) and check_key(item, key):
                    return True

    # If key not found in any nested structure
    return False

def capitalize_first_fourth(s: str) -> str:
    lower_s = s.lower()
    chars = list(lower_s)
    if len(chars) > 0:
        chars[0] = chars[0].upper()
    if len(chars) >= 4:
        chars[3] = chars[3].upper()
    return ''.join(chars)

def find_missing_positive(nums: list[int]) -> int:
    """
    Returns the smallest positive integer missing from the list.
    If all integers are non-positive, returns 1.

    Args:
        nums: A list of integers.

    Returns:
        The smallest positive integer not present in the list.
    """
    positives = {num for num in nums if num > 0}
    if not positives:
        return 1
    max_check = len(nums) + 1
    for i in range(1, max_check + 1):
        if i not in positives:
            return i

def max_subarray_sum(numbers, k):
    current_sum = sum(numbers[:k])
    max_sum = current_sum
    for i in range(k, len(numbers)):
        current_sum = current_sum - numbers[i - k] + numbers[i]
        if current_sum > max_sum:
            max_sum = current_sum
    return max_sum

def fibonacci(n):
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    a, b = 0, 1
    if n == 0:
        return a
    for _ in range(1, n):
        a, b = b, a + b
    return b

def gcd(a: int, b: int) -> int:
    while b != 0:
        a, b = b, a % b
    return abs(a)

def is_prime(n):
    # Numbers less than 2 are not prime
    if n < 2:
        return False

    # Check divisibility from 2 up to the square root of n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_prime(number):
    # Numbers less than 2 are not prime
    if number < 2:
        return False

    # 2 is the only even prime number
    if number == 2:
        return True

    # All other even numbers are not prime
    if number % 2 == 0:
        return False

    # Check odd factors up to sqrt(number)
    for i in range(3, int(number ** 0.5) + 1, 2):
        if number % i == 0:
            return False

    return True

from typing import List

def quicksort(arr: List[int]) -> List[int]:
    """
    Sorts a list of integers using the quicksort algorithm.

    Args:
        arr: A list of integers to be sorted.

    Returns:
        A new list containing the sorted elements of the input list.

    Raises:
        ValueError: If the input is not a list.
    """
    if not isinstance(arr, list):
        raise ValueError("Input must be a list")

    if len(arr) <= 1:
        return arr.copy()

    pivot = arr[-1]
    less_than_pivot: List[int] = []
    greater_than_pivot: List[int] = []

    for num in arr[:-1]:
        if num <= pivot:
            less_than_pivot.append(num)
        else:
            greater_than_pivot.append(num)

    return quicksort(less_than_pivot) + [pivot] + quicksort(greater_than_pivot)

def is_prime(n: int) -> bool:
    """Check if a number is prime.

    Args:
        n: The number to check for primality.

    Returns:
        True if the number is prime, False otherwise.
    """
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_valid(s: str) -> bool:
    allowed_punctuation = {',', '.', '!', '?'}
    has_lowercase = False
    for char in s:
        if char.islower():
            has_lowercase = True
        elif char not in allowed_punctuation:
            return False
    return has_lowercase

def is_palindrome(s):
    cleaned = ''.join([c.lower() for c in s if c.isalpha()])
    return cleaned == cleaned[::-1]

def generate_strings(n):
    if n == 0:
        return []
    result = list('abcdefghijklmnopqrstuvwxyz')
    for _ in range(n - 1):
        new_result = []
        for s in result:
            last_char = s[-1]
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c != last_char:
                    new_result.append(s + c)
        result = new_result
    return result
